insert into public.topics (module_id, slug, title, summary, position, published) select id, 'arrays-and-objects', 'Arrays and Objects', 'Storing collections and structured data.', 0, true from public.modules where level_id = 1 and title = 'JavaScript Essentials' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain arrays and objects in your own words.","Recognise and apply: an array holds an ordered list; index starts at 0.","Recognise and apply: an object holds named properties, accessed with dot notation.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers arrays and objects: storing collections and structured data. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that an array holds an ordered list; index starts at 0. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that an object holds named properties, accessed with dot notation. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how arrays and objects fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'javascript', 'const levels = [''Beginner'', ''Intermediate'', ''Advanced''];
