insert into public.topics (module_id, slug, title, summary, position, published) select id, 'events-and-event-listeners', 'Events and Event Listeners', 'Responding to clicks, input and other user actions.', 0, true from public.modules where level_id = 1 and title = 'JavaScript Essentials' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain events and event listeners in your own words.","Recognise and apply: an event listener runs a function when a named event fires.","Recognise and apply: preventDefault stops a form submitting and reloading the page.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers events and event listeners: responding to clicks, input and other user actions. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that an event listener runs a function when a named event fires. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that preventDefault stops a form submitting and reloading the page. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how events and event listeners fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'javascript', 'const form = document.querySelector(''form'');
