insert into public.topics (module_id, slug, title, summary, position, published) select id, 'beginner-practical-project', 'Beginner Practical Project', 'A complete beginner project combining semantic HTML, CSS and JavaScript.', 0, true from public.modules where level_id = 1 and title = 'Beginner Project' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain beginner practical project in your own words.","Recognise and apply: plan the page structure first, then style it, then add behaviour last.","Recognise and apply: every interactive element must work without JavaScript errors in the console.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers beginner practical project: a complete beginner project combining semantic HTML, CSS and JavaScript. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that plan the page structure first, then style it, then add behaviour last. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that every interactive element must work without JavaScript errors in the console. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how beginner practical project fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'html', '<!-- Project: a personal profile page -->
