insert into public.topics (module_id, slug, title, summary, position, published) select id, 'advanced-css', 'Advanced CSS', 'Custom properties, pseudo-classes, pseudo-elements and modern selectors.', 0, true from public.modules where level_id = 2 and title = 'Advanced HTML & CSS' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain advanced css in your own words.","Recognise and apply: CSS custom properties (--brand) let one change update a whole theme.","Recognise and apply: ::before and ::after add decorative content without extra markup.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers advanced css: custom properties, pseudo-classes, pseudo-elements and modern selectors. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that CSS custom properties (--brand) let one change update a whole theme. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that ::before and ::after add decorative content without extra markup. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how advanced css fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'css', ':root { --gold: #c9a227; --navy: #0a2a5e; }
