insert into public.topics (module_id, slug, title, summary, position, published) select id, 'css-animations-and-transitions', 'CSS Animations and Transitions', 'Smooth, purposeful motion with transitions and keyframes.', 0, true from public.modules where level_id = 2 and title = 'Advanced HTML & CSS' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain css animations and transitions in your own words.","Recognise and apply: transitions animate a property change over a duration.","Recognise and apply: keyframes define the steps of a named animation.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers css animations and transitions: smooth, purposeful motion with transitions and keyframes. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that transitions animate a property change over a duration. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that keyframes define the steps of a named animation. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how css animations and transitions fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'css', '.btn { transition: background 0.2s ease, transform 0.2s ease; }
