insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain javascript es6+ in your own words.","Recognise and apply: template literals use backticks and ${} to embed values in strings.","Recognise and apply: destructuring pulls named values out of objects and arrays in one line.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers javascript es6+: modern syntax: arrow functions, template literals, destructuring, spread and modules. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that template literals use backticks and ${} to embed values in strings. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that destructuring pulls named values out of objects and arrays in one line. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how javascript es6+ fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'javascript', 'const student = { name: ''Ada'', score: 8 };
